    for (mode = 0; mode < 2; mode++) {
        pthread_t a, b;
        double t0 = now();
        pthread_create(&a, NULL, worker, NULL);
        pthread_create(&b, NULL, worker, NULL);
        pthread_join(a, NULL);
        pthread_join(b, NULL);
        printf("%-7s result=%ld  time=%.0f ms\n", mode == 0 ? "mutex" : "atomic",
