import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.LongAdder;

public class RaceDemo {
    static int plain = 0;
    static int locked = 0;
    static final Object LOCK = new Object();
    static final AtomicInteger atomic = new AtomicInteger();
    static final LongAdder adder = new LongAdder();
    static volatile int vol = 0;

    static void run(String name, Runnable body) throws InterruptedException {
        Thread a = new Thread(body);
        Thread b = new Thread(body);
        long t0 = System.nanoTime();
        a.start(); b.start();
        a.join(); b.join();
        System.out.printf("%-12s %.0f ms%n", name, (System.nanoTime() - t0) / 1e6);
    }

    public static void main(String[] args) throws Exception {
        final int n = 5_000_000;
        run("plain int", () -> { for (int i = 0; i < n; i++) plain++; });
        run("volatile", () -> { for (int i = 0; i < n; i++) vol++; });
        run("synchronized", () -> {
            for (int i = 0; i < n; i++) {
                synchronized (LOCK) { locked++; }
            }
        });
        run("AtomicInt", () -> { for (int i = 0; i < n; i++) atomic.incrementAndGet(); });
        run("LongAdder", () -> { for (int i = 0; i < n; i++) adder.increment(); });
        System.out.println("plain        = " + plain);
        System.out.println("volatile     = " + vol);
        System.out.println("synchronized = " + locked);
        System.out.println("AtomicInt    = " + atomic.get());
        System.out.println("LongAdder    = " + adder.sum());
    }
}

