#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

#define CAP 4
#define ITEMS 100000

static int buf[CAP];
static int in = 0, out = 0;
static sem_t empty, full;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;

static void *producer(void *arg) {
    (void)arg;
    for (int i = 1; i <= ITEMS; i++) {
        sem_wait(&empty);               /* wait for a free slot */
        pthread_mutex_lock(&mu);
        buf[in] = i;
        in = (in + 1) % CAP;
        pthread_mutex_unlock(&mu);
        sem_post(&full);                /* announce one more item */
    }
    return NULL;
}

static void *consumer(void *arg) {
    long *sum = arg;
    for (int i = 1; i <= ITEMS; i++) {
        sem_wait(&full);                /* wait for an item */
        pthread_mutex_lock(&mu);
        *sum += buf[out];
        out = (out + 1) % CAP;
        pthread_mutex_unlock(&mu);
        sem_post(&empty);               /* announce one more free slot */
    }
    return NULL;
}

int main(void) {
    long sum = 0;
    pthread_t p, c;
    sem_init(&empty, 0, CAP);
    sem_init(&full, 0, 0);
    pthread_create(&p, NULL, producer, NULL);
    pthread_create(&c, NULL, consumer, &sum);
    pthread_join(p, NULL);
    pthread_join(c, NULL);
    printf("consumed sum=%ld expected=%ld\n", sum, (long)ITEMS * (ITEMS + 1) / 2);
    return 0;
}

import java.util.ArrayDeque;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedBuffer {
    private final ArrayDeque<Integer> items = new ArrayDeque<>();
    private final int capacity;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    BoundedBuffer(int capacity) { this.capacity = capacity; }

    void put(int v) throws InterruptedException {
        lock.lock();
        try {
            while (items.size() == capacity) {
                notFull.await();                  // loop guards against spurious wake-ups
            }
            items.addLast(v);
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    int take() throws InterruptedException {
        lock.lock();
        try {
            while (items.isEmpty()) notEmpty.await();
            int v = items.removeFirst();
            notFull.signal();
            return v;
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws Exception {
        BoundedBuffer buf = new BoundedBuffer(4);
        int producers = 3;
        int consumers = 3;
        int perProducer = 100_000;
        long[] sums = new long[consumers];
        Thread[] ts = new Thread[producers + consumers];
        for (int p = 0; p < producers; p++) {
            ts[p] = new Thread(() -> {
                try {
                    for (int i = 1; i <= perProducer; i++) buf.put(i);
                } catch (InterruptedException e) { }
            });
        }
        for (int c = 0; c < consumers; c++) {
            final int id = c;
            ts[producers + c] = new Thread(() -> {
                try {
                    for (int i = 0; i < perProducer; i++) sums[id] += buf.take();
                } catch (InterruptedException e) { }
            });
        }
        for (Thread t : ts) t.start();
        for (Thread t : ts) t.join();
        long total = 0;
        for (long s : sums) total += s;
        long expected = (long) producers * perProducer * (perProducer + 1) / 2;
        System.out.println("consumed sum = " + total + ", expected = " + expected);
    }
}

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadersWriters {
    static int a = 0;                           // invariant: a == b when no writer is active
    static int b = 0;
    static final ReentrantReadWriteLock RW = new ReentrantReadWriteLock();
    static final AtomicLong violations = new AtomicLong();
    static final AtomicLong reads = new AtomicLong();

    static void write(int v, boolean locked) {
        if (locked) RW.writeLock().lock();
        try { a = v; Thread.onSpinWait(); b = v; } finally { if (locked) RW.writeLock().unlock(); }
    }

    static void read(boolean locked) {
        if (locked) RW.readLock().lock();
        try {
            int x = a;
            Thread.onSpinWait();
            int y = b;
            reads.incrementAndGet();
            if (x != y) violations.incrementAndGet();
        } finally { if (locked) RW.readLock().unlock(); }
    }

    static void trial(boolean locked) throws Exception {
        violations.set(0); reads.set(0); a = 0; b = 0;
        long end = System.nanoTime() + 1_000_000_000L;
        Thread w = new Thread(() -> {
            int v = 0;
            while (System.nanoTime() < end) write(++v, locked);
        });
        Thread r1 = new Thread(() -> { while (System.nanoTime() < end) read(locked); });
        w.start(); r1.start();
        while (System.nanoTime() < end) read(locked);       // main thread is the second reader
        w.join(); r1.join();
        System.out.printf("locked=%-5s reads=%8d  inconsistent reads=%d%n",
                locked, reads.get(), violations.get());
    }

    public static void main(String[] args) throws Exception {
        trial(false);
        trial(true);
    }
}

import java.lang.management.ManagementFactory;
import java.util.concurrent.locks.ReentrantLock;

public class Philosophers {
    static final int N = 5;
    static final ReentrantLock[] fork = new ReentrantLock[N];
    static final int[] meals = new int[N];

    static void eat(int id, boolean ordered, int rounds, boolean pause) {
        int left = id, right = (id + 1) % N;
        int first = left, second = right;
        if (ordered && left > right) { first = right; second = left; }   // global lock order
        for (int r = 0; r < rounds; r++) {
            fork[first].lock();
            try {
                if (pause) { try { Thread.sleep(50); } catch (InterruptedException e) { return; } }
                fork[second].lock();
                try { meals[id]++; } finally { fork[second].unlock(); }
            } finally { fork[first].unlock(); }
        }
    }

    static Thread[] start(boolean ordered, int rounds, boolean pause) {
        Thread[] t = new Thread[N];
        for (int i = 0; i < N; i++) {
            final int id = i;
            t[i] = new Thread(() -> eat(id, ordered, rounds, pause), "philosopher-" + i);
            t[i].setDaemon(true);
            t[i].start();
        }
        return t;
    }

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < N; i++) fork[i] = new ReentrantLock();

        // 1. naive: everybody takes the left fork first, then pauses -> deadlock
        Thread[] naive = start(false, 1000, true);
        Thread.sleep(500);
        long[] dead = ManagementFactory.getThreadMXBean().findDeadlockedThreads();
        System.out.println("naive:   deadlocked threads = " + (dead == null ? 0 : dead.length));
        System.out.println("naive:   meals = " + java.util.Arrays.toString(meals));

        // 2. ordered: lower-numbered fork first -> no cycle possible
        java.util.Arrays.fill(meals, 0);
        for (int i = 0; i < N; i++) fork[i] = new ReentrantLock();
        Thread[] ok = start(true, 100_000, false);
        for (Thread t : ok) t.join();
        System.out.println("ordered: meals = " + java.util.Arrays.toString(meals));
    }
}

