import java.lang.management.ManagementFactory;
import java.lang.management.ThreadMXBean;
import java.util.concurrent.CountDownLatch;

public class SpinWait {
    static volatile boolean ready = false;

    static long cpuMs(Thread t) {
        ThreadMXBean mx = ManagementFactory.getThreadMXBean();
        return mx.getThreadCpuTime(t.threadId()) / 1_000_000;
    }

    public static void main(String[] args) throws Exception {
        Thread spin = new Thread(() -> { while (!ready) { } }, "spin-waiter");
        spin.setDaemon(true);
        spin.start();

        CountDownLatch latch = new CountDownLatch(1);
        Thread block = new Thread(() -> {
            try { latch.await(); } catch (InterruptedException e) { }
        }, "latch-waiter");
        block.setDaemon(true);
        block.start();

        Thread.sleep(2000);
        System.out.println("after 2000 ms of waiting for an event that has not happened yet:");
        System.out.println("  spin-waiter  cpu = " + cpuMs(spin) + " ms");
        System.out.println("  latch-waiter cpu = " + cpuMs(block) + " ms");
        ready = true;
        latch.countDown();
    }
}

