import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

public class Contention {
    static final Object LOCK = new Object();
    static long counter;
    static volatile long sink;

    static void slowLog() {                    // stands for formatting and writing a log line
        long x = 0;
        for (int i = 0; i < 20_000; i++) x += i ^ (x >>> 3);
        sink = x;
    }

    static long run(int threads, boolean wide, long millis) throws Exception {
        long[] done = new long[threads];
        List<Thread> ts = new ArrayList<>();
        long end = System.nanoTime() + millis * 1_000_000;
        for (int t = 0; t < threads; t++) {
            final int id = t;
            Thread th = new Thread(() -> {
                while (System.nanoTime() < end) {
                    if (wide) {
                        synchronized (LOCK) {                       // slow work inside the lock
                            slowLog();
                            counter++;
                        }
                    } else {
                        slowLog();                                  // slow work outside the lock
                        synchronized (LOCK) { counter++; }
                    }
                    done[id]++;
                }
            }, "worker-" + t);
            ts.add(th);
            th.start();
        }
        if (millis > 3000) {
            Thread.sleep(1500);
            System.out.println("sampling states of " + threads + " workers:");
            java.util.Map<Thread.State, Integer> m = new java.util.EnumMap<>(Thread.State.class);
            for (Thread th : ts) m.merge(th.getState(), 1, Integer::sum);
            System.out.println("  " + m);
        }
        for (Thread th : ts) th.join();
        long total = 0;
        for (long d : done) total += d;
        return total;
    }

    public static void main(String[] args) throws Exception {
        if (args.length > 0) { run(8, true, 4000); return; }
        run(2, false, 500);                                        // warm-up
        for (int threads : new int[]{1, 2, 8}) {
            long wide = run(threads, true, 2000);
            long narrow = run(threads, false, 2000);
            System.out.printf("threads=%d  wide lock: %6d ops   narrow lock: %6d ops%n",
                    threads, wide, narrow);
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Banker {
    static int[][] alloc = {{0,1,0},{2,0,0},{3,0,2},{2,1,1},{0,0,2}};
    static int[][] max   = {{7,5,3},{3,2,2},{9,0,2},{2,2,2},{4,3,3}};
    static int[] avail   = {3,3,2};

    static boolean le(int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) if (a[i] > b[i]) return false;
        return true;
    }

    /** Returns a safe sequence, or null when the state is unsafe. */
    static List<Integer> safeSequence(int[][] alloc, int[][] need, int[] avail) {
        int n = alloc.length;
        int[] work = avail.clone();
        boolean[] done = new boolean[n];
        List<Integer> seq = new ArrayList<>();
        boolean progress = true;
        while (seq.size() < n && progress) {
            progress = false;
            for (int p = 0; p < n; p++) {
                if (!done[p] && le(need[p], work)) {
                    for (int r = 0; r < work.length; r++) work[r] += alloc[p][r];
                    done[p] = true;
                    seq.add(p);
                    progress = true;
                }
            }
        }
        return seq.size() == n ? seq : null;
    }

    static int[][] needOf() {
        int[][] need = new int[alloc.length][3];
        for (int p = 0; p < alloc.length; p++)
            for (int r = 0; r < 3; r++) need[p][r] = max[p][r] - alloc[p][r];
        return need;
    }

    static void request(int p, int[] req) {
        int[][] need = needOf();
        String head = "P" + p + " requests " + Arrays.toString(req) + ": ";
        if (!le(req, need[p])) {
            System.out.println(head + "error, exceeds declared maximum");
            return;
        }
        if (!le(req, avail)) { System.out.println(head + "must wait, not available"); return; }
        int[][] a2 = new int[alloc.length][];
        for (int i = 0; i < alloc.length; i++) a2[i] = alloc[i].clone();
        int[] v2 = avail.clone();
        for (int r = 0; r < 3; r++) { a2[p][r] += req[r]; v2[r] -= req[r]; need[p][r] -= req[r]; }
        List<Integer> s = safeSequence(a2, need, v2);
        if (s == null) { System.out.println(head + "denied, resulting state is unsafe"); return; }
        alloc = a2; avail = v2;
        System.out.println(head + "granted, safe sequence " + s);
    }

    public static void main(String[] args) {
        System.out.println("need = " + Arrays.deepToString(needOf()));
        System.out.println("initial safe sequence: " + safeSequence(alloc, needOf(), avail));
        request(1, new int[]{1, 0, 2});
        request(4, new int[]{3, 3, 0});
        request(0, new int[]{0, 2, 0});
    }
}

public class TransferDeadlock {
    static class Account {
        final String id;
        long balance = 1000;
        Account(String id) { this.id = id; }
    }

    static void transfer(Account from, Account to, long amount) throws InterruptedException {
        synchronized (from) {
            Thread.sleep(100);          // widens the window, as slow I/O would in production
            synchronized (to) {
                from.balance -= amount;
                to.balance += amount;
            }
        }
    }

    static void run(Account from, Account to, long amount) {
        try {
            transfer(from, to, amount);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) throws Exception {
        Account a = new Account("A"), b = new Account("B");
        Thread t1 = new Thread(() -> run(a, b, 10), "transfer-A-to-B");
        Thread t2 = new Thread(() -> run(b, a, 20), "transfer-B-to-A");
        t1.start(); t2.start();
        t1.join(); t2.join();                // never returns
        System.out.println("done");
    }
}

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class OrderedTransfer {
    static class Account {
        final long id;
        final ReentrantLock lock = new ReentrantLock();
        long balance = 1000;
        Account(long id) { this.id = id; }
    }

    /** Fix 1: acquire locks in a global order (by account id). */
    static void transferOrdered(Account from, Account to, long amount) {
        Account first = from.id < to.id ? from : to;
        Account second = first == from ? to : from;
        first.lock.lock();
        try {
            second.lock.lock();
            try { from.balance -= amount; to.balance += amount; } finally { second.lock.unlock(); }
        } finally { first.lock.unlock(); }
    }

    /** Fix 2: bounded wait; give up instead of waiting forever. */
    static boolean transferTimed(Account from, Account to, long amount)
            throws InterruptedException {
        if (!from.lock.tryLock(100, TimeUnit.MILLISECONDS)) return false;
        try {
            if (!to.lock.tryLock(100, TimeUnit.MILLISECONDS)) return false;
            try {
                from.balance -= amount;
                to.balance += amount;
                return true;
            } finally {
                to.lock.unlock();
            }
        } finally { from.lock.unlock(); }
    }

    public static void main(String[] args) throws Exception {
        Account a = new Account(1), b = new Account(2);
        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 100_000; i++) transferOrdered(a, b, 1);
        });
        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 100_000; i++) transferOrdered(b, a, 2);
        });
        t1.start(); t2.start(); t1.join(); t2.join();
        System.out.println("ordered: A=" + a.balance + " B=" + b.balance
                + " total=" + (a.balance + b.balance));

        a.lock.lock();                                   // simulate a stuck holder on this thread
        Thread t3 = new Thread(() -> {
            try { System.out.println("timed transfer succeeded = " + transferTimed(b, a, 5)); }
            catch (InterruptedException e) { }
        });
        t3.start(); t3.join();
        a.lock.unlock();
    }
}

#define _GNU_SOURCE
#include <pthread.h>
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

static pthread_mutex_t m;
static volatile int l_has_lock = 0;
static double h_wait_ms;

static double now_ms(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec * 1e3 + t.tv_nsec / 1e6;
}

/* busy loop on the wall clock; the process is pinned to one CPU with taskset */
static void burn_ms(double ms) {
    double end = now_ms() + ms;
    while (now_ms() < end) { }
}

static void *low(void *a)  { (void)a; pthread_mutex_lock(&m); l_has_lock = 1; burn_ms(50);
                              pthread_mutex_unlock(&m); return NULL; }
static void *med(void *a)  { (void)a; burn_ms(300); return NULL; }
static void *high(void *a) { (void)a; double t0 = now_ms(); pthread_mutex_lock(&m);
                              h_wait_ms = now_ms() - t0; pthread_mutex_unlock(&m); return NULL; }

static pthread_t spawn(void *(*fn)(void *), int prio) {
    pthread_attr_t at;
    struct sched_param sp = { .sched_priority = prio };
    pthread_t t;
    pthread_attr_init(&at);
    pthread_attr_setinheritsched(&at, PTHREAD_EXPLICIT_SCHED);
    pthread_attr_setschedpolicy(&at, SCHED_FIFO);
    pthread_attr_setschedparam(&at, &sp);
    int rc = pthread_create(&t, &at, fn, NULL);
    if (rc) { fprintf(stderr, "pthread_create: %d\n", rc); exit(1); }
    return t;
}

int main(int argc, char **argv) {
    int inherit = argc > 1;
    struct sched_param me = { .sched_priority = 40 };
    if (sched_setscheduler(0, SCHED_FIFO, &me)) { perror("sched_setscheduler"); return 1; }
    pthread_mutexattr_t ma;
    pthread_mutexattr_init(&ma);
    if (inherit) pthread_mutexattr_setprotocol(&ma, PTHREAD_PRIO_INHERIT);
    pthread_mutex_init(&m, &ma);

    pthread_t l = spawn(low, 10);
    while (!l_has_lock) usleep(1000);       /* main (prio 40) sleeps; L runs and takes the lock */
    pthread_t h = spawn(high, 30);          /* H preempts L, then blocks on the mutex */
    pthread_t md = spawn(med, 20);          /* M becomes runnable and outranks L */
    pthread_join(h, NULL); pthread_join(md, NULL); pthread_join(l, NULL);
    printf("%s: high-priority thread waited %.0f ms for a lock held for 50 ms of work\n",
           inherit ? "PTHREAD_PRIO_INHERIT" : "default mutex       ", h_wait_ms);
    return 0;
}

