import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

public class Pinning {
    static void work(boolean useSynchronized) {
        Object mon = new Object();
        ReentrantLock rl = new ReentrantLock();
        try {
            if (useSynchronized) {
                synchronized (mon) { Thread.sleep(200); }
            } else {
                rl.lock();
                try { Thread.sleep(200); } finally { rl.unlock(); }
            }
        } catch (InterruptedException e) { }
    }

    static long time(boolean useSynchronized) throws Exception {
        List<Thread> ts = new ArrayList<>();
        long t0 = System.nanoTime();
        for (int i = 0; i < 4; i++) ts.add(Thread.ofVirtual().start(() -> work(useSynchronized)));
        for (Thread t : ts) t.join();
        return (System.nanoTime() - t0) / 1_000_000;
    }

    public static void main(String[] args) throws Exception {
        time(false);                                           // warm-up
        System.out.println("4 virtual threads, 1 carrier thread,"
                + " each sleeps 200 ms while holding a lock");
        System.out.println("  ReentrantLock: " + time(false) + " ms");
        System.out.println("  synchronized : " + time(true) + " ms");
    }
}

import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

public class PoolSaturation {
    public static void main(String[] args) throws Exception {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(10, 10, 0, TimeUnit.SECONDS,
                new LinkedBlockingQueue<>());
        AtomicLong lastLatencyMs = new AtomicLong();
        int perSecond = 300;               // arrival rate; capacity is 10 / 0.05 s = 200 per second
        for (int sec = 1; sec <= 6; sec++) {
            for (int i = 0; i < perSecond; i++) {
                final long submitted = System.nanoTime();
                pool.execute(() -> {
                    try {
                        Thread.sleep(50);
                    } catch (InterruptedException e) {
                        return;
                    }
                    lastLatencyMs.set((System.nanoTime() - submitted) / 1_000_000);
                });
                Thread.sleep(1000 / perSecond);
            }
            System.out.printf("t=%ds  active=%d  queued=%4d  completed=%4d  last latency=%d ms%n",
                    sec, pool.getActiveCount(), pool.getQueue().size(),
                    pool.getCompletedTaskCount(), lastLatencyMs.get());
        }
        pool.shutdownNow();
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class PoolStarve {
    public static void main(String[] args) throws Exception {
        AtomicInteger seq = new AtomicInteger();
        ThreadPoolExecutor pool = new ThreadPoolExecutor(4, 4, 0, TimeUnit.SECONDS,
                new LinkedBlockingQueue<>(), r -> {
                    Thread t = new Thread(r, "http-" + seq.incrementAndGet());
                    t.setDaemon(true);
                    return t;
                });

        // Each "request" submits a sub-task to the SAME pool and waits for it.
        for (int i = 0; i < 6; i++) {
            final int req = i;
            pool.execute(() -> {
                Future<String> sub = pool.submit(() -> "price-for-" + req);
                try { System.out.println(sub.get()); } catch (Exception e) { }
            });
        }
        Thread.sleep(1000);
        System.out.println("pool=" + pool.getPoolSize() + " active=" + pool.getActiveCount()
                + " queued=" + pool.getQueue().size()
                + " completed=" + pool.getCompletedTaskCount());
        System.out.println("pid=" + ProcessHandle.current().pid());
        Thread.sleep(15_000);
    }
}

import java.util.concurrent.*;

public class PoolLeak {
    /** Minimal bounded connection pool; acquire() waits up to the timeout. */
    static class Pool {
        private final Semaphore permits;
        private final long timeoutMs;
        Pool(int size, long timeoutMs) {
            permits = new Semaphore(size);
            this.timeoutMs = timeoutMs;
        }
        void acquire() throws Exception {
            if (!permits.tryAcquire(timeoutMs, TimeUnit.MILLISECONDS))
                throw new TimeoutException("Connection is not available, request timed out after "
                        + timeoutMs + "ms");
        }
        void release() { permits.release(); }
        int idle() { return permits.availablePermits(); }
    }

    static void handleLeaky(Pool pool, int i) throws Exception {
        pool.acquire();
        if (i % 3 == 0) throw new IllegalStateException("validation failed for order " + i);
        pool.release();                         // skipped when the exception is thrown
    }

    static void handleSafe(Pool pool, int i) throws Exception {
        pool.acquire();
        try {
            if (i % 3 == 0) throw new IllegalStateException("validation failed for order " + i);
        } finally {
            pool.release();                     // always runs
        }
    }

    interface Handler { void run(Pool p, int i) throws Exception; }

    static void drive(String name, Handler h) throws Exception {
        Pool pool = new Pool(5, 200);
        int ok = 0, bad = 0, timeouts = 0;
        for (int i = 1; i <= 30; i++) {
            try { h.run(pool, i); ok++; }
            catch (TimeoutException e) { timeouts++; }
            catch (IllegalStateException e) { bad++; }
        }
        System.out.printf("%-6s ok=%d business-errors=%d pool-timeouts=%d idle-connections=%d%n",
                name, ok, bad, timeouts, pool.idle());
    }

    public static void main(String[] args) throws Exception {
        drive("leaky", PoolLeak::handleLeaky);
        drive("safe", PoolLeak::handleSafe);
    }
}
